# coding: utf8
from __future__ import unicode_literals

import re

from ...gold import iob_to_biluo


def conllu2json(input_data, n_sents=10, use_morphology=False, lang=None, **_):
    """
    Convert conllu files into JSON format for use with train cli.
    use_morphology parameter enables appending morphology to tags, which is
    useful for languages such as Spanish, where UD tags are not so rich.

    Extract NER tags if available and convert them so that they follow
    BILUO and the Wikipedia scheme
    """
    # by @dvsrepo, via #11 explosion/spacy-dev-resources
    # by @katarkor
    result_docs = []
    pending = []
    conll_iter = read_conllx(input_data, use_morphology=use_morphology)
    ner_checked = False
    ner_present = False
    idx = -1
    for raw_text, tok_groups in conll_iter:
        idx += 1
        first_group = tok_groups[0]
        sent_data = first_group[0]
        if ner_checked is False:
            ner_present = is_ner(sent_data[5][0])
            ner_checked = True
        pending.append(generate_sentence(sent_data, ner_present))
        # Real-sized documents could be extracted using the comments on the
        # conluu document
        if (len(pending) % n_sents) == 0:
            result_docs.append(create_doc(pending, idx))
            pending = []
    if len(pending) > 0:
        result_docs.append(create_doc(pending, idx))
    return result_docs


def is_ner(tag):
    """
    Check the 10th column of the first token to determine if the file contains
    NER tags
    """
    if re.match("([A-Z_]+)-([A-Z_]+)", tag):
        return True
    if tag == "O":
        return True
    return False


def read_conllx(input_data, use_morphology=False, n=0):
    count = 0
    for block in input_data.strip().split("\n\n"):
        block_lines = block.strip().split("\n")
        if block_lines:
            while block_lines[0].startswith("#"):
                del block_lines[0]
            collected = []
            for raw_line in block_lines:

                fields = raw_line.split("\t")
                tok_id, word, lemma, pos, tag, morph, head, dep, _1, iob = fields
                if "-" in tok_id or "." in tok_id:
                    continue
                try:
                    tok_id = int(tok_id) - 1
                    if head != "0":
                        head = int(head) - 1
                    else:
                        head = tok_id
                    if dep == "root":
                        dep = "ROOT"
                    if tag == "_":
                        tag = pos
                    if use_morphology:
                        tag = tag + "__" + morph
                    if not iob:
                        iob = "O"
                    collected.append((tok_id, word, tag, head, dep, iob))
                except:  # noqa: E722
                    print(raw_line)
                    raise
            columns = [list(col) for col in zip(*collected)]
            yield (None, [[columns, []]])
            count += 1
            if n >= 1 and count >= n:
                break


def simplify_tags(iob):
    """
    Simplify tags obtained from the dataset in order to follow Wikipedia
    scheme (PER, LOC, ORG, MISC). 'PER', 'LOC' and 'ORG' keep their tags, while
    'GPE_LOC' is simplified to 'LOC', 'GPE_ORG' to 'ORG' and all remaining tags to
    'MISC'.
    """
    simplified = []
    for tag in iob:
        m = re.match("([A-Z_]+)-([A-Z_]+)", tag)
        if m:
            prefix = m.group(1)
            suffix = m.group(2)
            if suffix == "GPE_LOC":
                suffix = "LOC"
            elif suffix == "GPE_ORG":
                suffix = "ORG"
            elif suffix not in ("PER", "LOC", "ORG"):
                suffix = "MISC"
            tag = "{}-{}".format(prefix, suffix)
        simplified.append(tag)
    return simplified


def generate_sentence(sent, has_ner_tags):
    (id_, word, tag, head, dep, iob) = sent
    tokens = []
    if has_ner_tags:
        iob = simplify_tags(iob)
        biluo = iob_to_biluo(iob)
    for pos_idx, tok_id in enumerate(id_):
        entry = {
            "id": tok_id,
            "orth": word[pos_idx],
            "tag": tag[pos_idx],
            "head": head[pos_idx] - tok_id,
            "dep": dep[pos_idx],
        }
        if has_ner_tags:
            entry["ner"] = biluo[pos_idx]
        tokens.append(entry)
    return {"tokens": tokens}


def create_doc(sentences, id):
    paragraph = {"sentences": sentences}
    doc = {"id": id, "paragraphs": [paragraph]}
    return doc
